import{_ as s,o as a,c as t,a2 as e}from"./chunks/framework.BZAK_utg.js";const c=JSON.parse('{"title":"Linux开启WiFi热点反向共享网络给iPhone的方法","description":"","frontmatter":{"title":"Linux开启WiFi热点反向共享网络给iPhone的方法","date":"2026-08-08","categories":["安装配置","应用软件"],"tags":["Linux"],"prevTitle":"命令备忘录：Docker","prevLink":"./命令备忘录：Docker.html","nextTitle":"命令备忘录：Linux","nextLink":"./命令备忘录：Linux.html"},"headers":[],"relativePath":"posts/安装配置/Linux开启WiFi热点反向共享网络给iPhone的方法.md","filePath":"posts/安装配置/Linux开启WiFi热点反向共享网络给iPhone的方法.md"}'),n={name:"posts/安装配置/Linux开启WiFi热点反向共享网络给iPhone的方法.md"};function l(p,i,h,d,o,k){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="linux开启wifi热点反向共享网络给iphone的方法" tabindex="-1">Linux开启WiFi热点反向共享网络给iPhone的方法 <a class="header-anchor" href="#linux开启wifi热点反向共享网络给iphone的方法" aria-label="Permalink to &quot;Linux开启WiFi热点反向共享网络给iPhone的方法&quot;">​</a></h1><p>针对部分网络受限的情况，需要将Linux的网络反向共享给移动设备。对于Android，可以通过<code>gnirehtet</code>等软件实现反向共享网络。但iPhone相对封闭，无法通过类似的软件实现该功能。下文将基于此背景，介绍几种Linux反向共享网络给iPhone的方式。</p><h2 id="一、方案选型" tabindex="-1">一、方案选型 <a class="header-anchor" href="#一、方案选型" aria-label="Permalink to &quot;一、方案选型&quot;">​</a></h2><p>在“路由器 --&gt; Linux --&gt; iPhone”的网络链路中，Linux作为网络的客户端和服务端，有不同的接入和共享网络的方式，如下所示：</p><ul><li>Linux作为网络客户端（路由器 --&gt; Linux）：【有线以太网】、【无线WiFi】。</li><li>Linux作为网络服务端（Linux --&gt; iPhone）：【无线WiFi】、【USB】、【蓝牙】。</li></ul><table tabindex="0"><thead><tr><th>连接方式</th><th>协议</th><th>服务端角色</th><th>客户端角色</th><th>传输方向</th></tr></thead><tbody><tr><td>有线以太网</td><td>IEEE 802.3</td><td>-</td><td>-</td><td>路由器 → Linux</td></tr><tr><td>无线WiFi</td><td>IEEE 802.11</td><td>AP</td><td>Station</td><td>路由器 → Linux<br>Linux → iPhone</td></tr><tr><td>USB</td><td>CDC-ECM / CDC‑NCM</td><td>Device</td><td>Host</td><td>Linux → iPhone</td></tr><tr><td>蓝牙</td><td>PAN</td><td>NAP</td><td>PANU</td><td>Linux → iPhone</td></tr></tbody></table><p>对于上述连接方式：</p><ul><li>USB方式暂不考虑：因为Linux的USB口不支持服务端Device模式，无法模拟成iPhone的网卡设备。再加上，iPhone对CDC-ECM/CDC‑NCM的支持情况有待进一步验证。</li><li>蓝牙方式暂不考虑：因为iPhone不再支持PAN的客户端PANU模式，无法通过蓝牙获取Linux提供的网络。再加上，蓝牙网络传输速率较低。</li></ul><p>综上，Linux作为网络服务端，共享网络的方式的有效方式只有一种：无线WiFi。所以讨论的主题开始从“Linux反向共享网络给iPhone”的多种方式，限定为“Linux开启WiFi热点”这一种方式。最终可供选择的连接组合为：</p><ul><li>有线输入无线输出：Linux连接有线以太网，通过WiFi热点将网络共享给iPhone。</li><li>无线输入无线输出：Linux连接无线WiFi，通过WiFi热点将网络共享给iPhone。</li></ul><h2 id="二、有线输入无线输出" tabindex="-1">二、有线输入无线输出 <a class="header-anchor" href="#二、有线输入无线输出" aria-label="Permalink to &quot;二、有线输入无线输出&quot;">​</a></h2><p>Linux连接有线以太网，通过WiFi热点将网络共享给iPhone。该方式设置起来相对简单，因为不涉及网卡冲突：有线网卡用于Linux的网络输入、无线网卡用于Linux的网络输出。</p><p>安装wifi热点工具<code>linux-wifi-hotspot</code>:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux-wifi-hotspot</span></span></code></pre></div><p>随后，使用下述命令创建WiFi热点：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create_ap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wlan0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enp0s31f6</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> access_point_ssid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passphrase</span></span></code></pre></div><p>或者，也可以按照下述流程创建并连接WiFi热点：</p><ul><li>打开<code>linux-wifi-hotspot</code>软件。</li><li>填入【SSID】和【Password】，【Wifi interface】选择【wlan0】，【Internet interface】选择【enp0s31f6】。</li><li>点击【create hotspot】，左下角显示【Running as PID: xxx】，说明启动成功</li><li>点击【Open QR】，显示二维码。</li><li>打开iPhone相机，扫码后点击【加入xxx网络】，访问iPhone上的任意网络应用，验证网络是否正常。</li></ul><h2 id="三、无线输入无线输出" tabindex="-1">三、无线输入无线输出 <a class="header-anchor" href="#三、无线输入无线输出" aria-label="Permalink to &quot;三、无线输入无线输出&quot;">​</a></h2><p>Linux连接无线WiFi，通过WiFi热点将网络共享给iPhone。该方式需要同时运行无线网卡的Station模式和AP模式，即：无线网卡同时用于网络的输入和输出。</p><p><strong>（1）检查硬件是否支持Station和AP并行模式</strong></p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看网卡支持模式：输出结果有AP，则说明支持AP模式</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Supported interface modes&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看有效网卡组合模式：managed和AP在同一个组里面并且各自的数量&gt;=1，则说明支持Station和AP并行模式</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;valid interface combinations&quot;</span></span></code></pre></div><p><strong>（2）启动Station：关闭NetworkManager并使用wpa_supplicant手工联网</strong></p><p><code>NetworkManager</code>与<code>linux-wifi-hotspot</code>存在冲突，临时关闭<code>NetworkManager</code>：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NetworkManager</span></span></code></pre></div><p>使用<code>wpa_supplicant</code>手工联网：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wpa_passphrase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HUAWEI-AB5KMB_2.4G</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12345678</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/wpa.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wpa_supplicant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wlan0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/wpa.conf</span></span></code></pre></div><p>验证网络情况（查看wlan0是否UP，IP是否正常显示）：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span></span></code></pre></div><p>另外，后续若需要还原<code>NetworkManager</code>，只需杀掉<code>wpa_supplicant</code>进程，并重新启用<code>NetworkManager</code>即可：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> killall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wpa_supplicant</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NetworkManager</span></span></code></pre></div><p><strong>（3）启动AP：使用create_ap或linux-wifi-hotspot创建WiFi热点</strong></p><p>如果没有安装wifi热点工具<code>linux-wifi-hotspot</code>，安装它:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux-wifi-hotspot</span></span></code></pre></div><p>创建WiFi热点：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create_ap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wlan0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wlan0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Hotspot666</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12345678</span></span></code></pre></div><p>或者，也可使用<code>linux-wifi-hotspot</code>界面创建WiFi热点。</p><p>随后，可以在iPhone等任意设备WiFi列表中连接该WiFi热点。</p><p><strong>（4）不支持5GHz频段的情况说明</strong></p><p>由于硬件限制，Linux接入5GHz频段的WiFi网络后，<code>linux-wifi-hotspot</code>/<code>create_ap</code>可能无法创建5Ghz频段的热点，建议切换到2.4GHz频段创建热点。官方说明如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Support both 2.4GHz and 5GHz (Need to be compatible with your wifi adapter). Ex: You have connected to the 5GHz network and share a connection with 2.4GHz.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Sometimes there are troubles with 5Ghz bands due to some vendor restrictions. If you cannot start the hotspot while you are connected to the 5Ghz band, Unselect Auto and select 2.4Ghz in frequency selection.</span></span></code></pre></div><p>但与此同时，根据<code>iw list | grep -A 4 &quot;valid interface combinations&quot;</code>的结果<code>channels &lt;= 1</code>，硬件又要求managed（Station）和 AP共用同一个channel，5GHz和2.4GHz必定不在同一个channel。</p><p>因此，针对接入WiFi网络频段是5GHz的场景，如果想开启WiFi热点，只能使用外置网卡，或使用有线接入方式。</p>`,43)])])}const F=s(n,[["render",l]]);export{c as __pageData,F as default};
